fn fixed_size(s: &str, size: usize) -> String {
    // Truncate to size chars (not bytes?) and pad left with spaces to size.
    // Need to handle unicode? Use chars count.
    let chars: Vec<char> = s.chars().collect();
    if chars.len() > size {
        chars[..size].iter().collect()
    } else if chars.len() < size {
        let pad = size - chars.len();
        format!("{}{}", " ".repeat(pad), s)
    } else {
        s.to_string()
    }
}

fn min_size(s: &str, size: usize) -> String {
    let len = s.chars().count();
    if len < size {
        format!("{}{}", " ".repeat(size - len), s)
    } else {
        s.to_string()
    }
}

fn level_style(s: &str) -> String {
    // Trim spaces? Earlier " WARN" (with leading space) gave yellow, so trim and case-insensitive?
    let t = s.trim().to_lowercase();
    let code = match t.as_str() {
        "trace" => "36",
        "debug" => "34",
        "info" => "32",
        "warn" | "warning" => "33",
        "error" | "err" => "31",
        _ => "35",
    };
    format!("\x1b[1;{}m{}\x1b[0m", code, s)
}

