    // Number? Try parse
    if path.chars().next().map(|c| c.is_ascii_digit() || c == '-' || c == '+' || c == '.').unwrap_or(false) {
        if let Ok(n) = serde_json::from_str::<serde_json::Number>(path) {
            return JsonValue::Number(n);
        }
    }
    // Handle this, @index, etc. These are resolved via data context which includes them? For each loops, we push them into data.
    // Normal path with dots and brackets: e.g., "nested.a", "arr.[0]", "arr.0", "a.b.c"
    // Split by '.' but handle "[...]"?
    // In handlebars, "arr.[0]" means arr[0], "arr.0" also means arr[0].
    // We'll parse: split by '.', for each part, handle "[n]"?
    let mut current = data;
    // Special: "this" refers to current context? In handlebars, {{this}} inside each refers to current item. Our data for each will have "this" key? We'll handle by looking up "this" in data.
    // Split path
    let parts = split_path(path);
    for part in parts {
        if part.is_empty() { continue; }
        // Check for "[n]"? Part could be "[0]" or "arr[0]"? Actually split_path should handle? Let's implement split_path to return clean parts.
        // For simplicity, handle part like "[0]" as index, and "arr[0]"? No, our split_path splits by '.' only, so "arr[0]" would be one part "arr[0]"? But our earlier paths are "arr.[0]" (with dot) or "arr.0" (with dot). What about "arr[0]" without dot? Does handlebars support {{arr[0]}}? Possibly. Let's handle both: if part contains '[', parse.
        if part.starts_with('[') && part.ends_with(']') {
            // Index like "[0]" or '["key"]'?
            let idx_str = &part[1..part.len()-1];
            let idx_str = idx_str.trim();
            // If quoted string, treat as key
            if (idx_str.starts_with('"') && idx_str.ends_with('"')) || (idx_str.starts_with('\'') && idx_str.ends_with('\'')) {
                let key = &idx_str[1..idx_str.len()-1];
                if let JsonValue::Object(map) = current {
                    if let Some(v) = map.get(key) { current = v; } else { return JsonValue::Null; }
                } else { return JsonValue::Null; }
            } else {
                // Numeric index?
                if let Ok(idx) = idx_str.parse::<usize>() {
                    if let JsonValue::Array(arr) = current {
                        if idx < arr.len() { current = &arr[idx]; } else { return JsonValue::Null; }
                    } else { return JsonValue::Null; }
                } else {
                    // Treat as key? e.g., [key] without quotes? Unlikely.
                    if let JsonValue::Object(map) = current {
                        if let Some(v) = map.get(idx_str) { current = v; } else { return JsonValue::Null; }
                    } else { return JsonValue::Null; }
                }
            }
        } else if part.contains('[') {
            // Like "arr[0]" or "arr[0][1]"? Split?
            // Parse base + indices
            let mut base_end = part.find('[').unwrap();
            let base = &part[..base_end];
            if !base.is_empty() {
                if let JsonValue::Object(map) = current {
                    if let Some(v) = map.get(base) { current = v; } else { return JsonValue::Null; }
                } else { return JsonValue::Null; }
            }
            // Now parse indices: [0][1] etc.
            let mut rest = &part[base_end..];
            while rest.starts_with('[') {
                if let Some(end) = rest.find(']') {
                    let idx_str = &rest[1..end];
                    let idx_str = idx_str.trim();
                    if (idx_str.starts_with('"') && idx_str.ends_with('"')) || (idx_str.starts_with('\'') && idx_str.ends_with('\'')) {
                        let key = &idx_str[1..idx_str.len()-1];
                        if let JsonValue::Object(map) = current {
                            if let Some(v) = map.get(key) { current = v; } else { return JsonValue::Null; }
                        } else { return JsonValue::Null; }
                    } else {
                        if let Ok(idx) = idx_str.parse::<usize>() {
                            if let JsonValue::Array(arr) = current {
                                if idx < arr.len() { current = &arr[idx]; } else { return JsonValue::Null; }
                            } else { return JsonValue::Null; }
                        } else {
                            if let JsonValue::Object(map) = current {
                                if let Some(v) = map.get(idx_str) { current = v; } else { return JsonValue::Null; }
                            } else { return JsonValue::Null; }
                        }
                    }
                    rest = &rest[end+1..];
                } else {
                    return JsonValue::Null;
                }
            }
            if !rest.is_empty() {
                return JsonValue::Null;
            }
        } else {
            // Normal key or numeric index for arrays? e.g., "0" for arr.0?
            if let JsonValue::Object(map) = current {
                if let Some(v) = map.get(part.as_str()) { current = v; }
                else {
                    // Try numeric? If current is object but part is numeric, maybe miss? Return null.
                    return JsonValue::Null;
                }
            } else if let JsonValue::Array(arr) = current {
                // Part could be numeric index like "0"
                if let Ok(idx) = part.parse::<usize>() {
                    if idx < arr.len() { current = &arr[idx]; } else { return JsonValue::Null; }
                } else {
                    return JsonValue::Null;
                }
            } else {
                return JsonValue::Null;
            }
        }
    }
    current.clone()
}

fn split_path(path: &str) -> Vec<String> {
    // Split by '.' but respect brackets? e.g., "arr.[0]" -> ["arr", "[0]"], "a.b" -> ["a","b"], "a" -> ["a"]
    let mut res = Vec::new();
    let mut cur = String::new();
    let mut in_bracket = false;
    for c in path.chars() {
        if c == '[' {
            in_bracket = true;
            cur.push(c);
        } else if c == ']' {
            in_bracket = false;
            cur.push(c);
        } else if c == '.' && !in_bracket {
            res.push(cur.clone());
            cur.clear();
        } else {
            cur.push(c);
        }
    }
    res.push(cur);
    // Filter empty? For "arr.[0]", split gives ["arr", "[0]"] (second starts with '['). Good. For ".", etc.
    res.into_iter().filter(|s| !s.is_empty()).collect()
}

fn json_to_string(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => String::new(),
        JsonValue::Bool(b) => b.to_string(),
        JsonValue::Number(n) => n.to_string(),
        JsonValue::String(s) => s.clone(),
        JsonValue::Array(arr) => {
            // Render as "[a, b]" with elements stringified? For strings, without quotes? Earlier [a, b] for ["a","b"] without quotes. For numbers, same. How to stringify elements? Use json_to_string for each? For ["a","b"], each is String "a" -> "a", joined with ", " inside [].
            let parts: Vec<String> = arr.iter().map(|e| {
                match e {
                    JsonValue::String(s) => s.clone(),
                    JsonValue::Number(n) => n.to_string(),
                    JsonValue::Bool(b) => b.to_string(),
                    JsonValue::Null => "null".to_string(),
                    JsonValue::Array(_) => json_to_string(e),
                    JsonValue::Object(_) => "[object]".to_string(),
                }
            }).collect();
            format!("[{}]", parts.join(", "))
        }
        JsonValue::Object(_) => "[object]".to_string(),
    }
}

fn is_truthy(v: &JsonValue) -> bool {
    match v {
        JsonValue::Null => false,
        JsonValue::Bool(b) => *b,
        JsonValue::String(s) => !s.is_empty(),
        JsonValue::Number(n) => {
            if let Some(i) = n.as_i64() { i != 0 }
            else if let Some(u) = n.as_u64() { u != 0 }
            else if let Some(f) = n.as_f64() { f != 0.0 }
            else { true }
        }
        JsonValue::Array(a) => !a.is_empty(),
        JsonValue::Object(m) => !m.is_empty(),
    }
}

fn render_nodes(nodes: &[Node], data: &JsonValue, template_name: &str) -> Result<String, String> {
    let mut out = String::new();
    for node in nodes {
        match node {
            Node::Text(s) => out.push_str(s),
            Node::Var(path) => {
                let v = lookup_path(data, path);
                out.push_str(&json_to_string(&v));
            }
            Node::Helper(call) => {
                let s = eval_helper(call, data, template_name)?;
                out.push_str(&s);
            }
            Node::Section { name, param, children, else_children } => {
                if name == "if" {
                    let cond = if let Some(p) = param {
                        eval_param_to_json(p, data, template_name)?
                    } else {
                        return Err(format!("Helper/Decorator if param at index 0 required but not found"));
                    };
                    if is_truthy(&cond) {
                        out.push_str(&render_nodes(children, data, template_name)?);
                    } else if let Some(else_ch) = else_children {
                        out.push_str(&render_nodes(else_ch, data, template_name)?);
                    }
                } else if name == "unless" {
                    let cond = if let Some(p) = param {
                        eval_param_to_json(p, data, template_name)?
                    } else {
                        return Err(format!("Helper/Decorator unless param at index 0 required but not found"));
                    };
                    if !is_truthy(&cond) {
                        out.push_str(&render_nodes(children, data, template_name)?);
                    } else if let Some(else_ch) = else_children {
                        out.push_str(&render_nodes(else_ch, data, template_name)?);
                    }
                } else if name == "each" {
                    let arr_val = if let Some(p) = param {
                        eval_param_to_json(p, data, template_name)?
                    } else {
                        return Err(format!("Helper/Decorator each param at index 0 required but not found"));
                    };
                    match arr_val {
                        JsonValue::Array(arr) => {
                            if arr.is_empty() {
                                if let Some(else_ch) = else_children {
                                    out.push_str(&render_nodes(else_ch, data, template_name)?);
                                }
                            } else {
                                for (i, item) in arr.iter().enumerate() {
                                    // Create new data context: merge? In handlebars, each changes context to item, with @index etc. For simplicity, create new object with parent data + this, @index, etc.
                                    // If item is object, merge? Actually handlebars each with object item: context is item, but parent accessible via ../? We ignore parent.
                                    // For our purposes, simple: create data with "this" = item, "@index" = i, plus if item is object, include its keys? And also include parent keys? Let's include parent + item.
                                    let mut new_map = match data {
                                        JsonValue::Object(m) => m.clone(),
                                        _ => serde_json::Map::new(),
                                    };
                                    new_map.insert("this".to_string(), item.clone());
                                    new_map.insert("@index".to_string(), JsonValue::Number(serde_json::Number::from(i as u64)));
                                    new_map.insert("@first".to_string(), JsonValue::Bool(i==0));
                                    new_map.insert("@last".to_string(), JsonValue::Bool(i==arr.len()-1));
                                    if let JsonValue::Object(im) = item {
                                        for (k,v) in im { new_map.insert(k.clone(), v.clone()); }
                                    }
                                    let new_data = JsonValue::Object(new_map);
                                    out.push_str(&render_nodes(children, &new_data, template_name)?);
                                }
                            }
                        }
                        JsonValue::Object(map) => {
                            if map.is_empty() {
                                if let Some(else_ch) = else_children {
                                    out.push_str(&render_nodes(else_ch, data, template_name)?);
                                }
                            } else {
                                // Sort keys? Handlebars each for objects iterates sorted? Our earlier test with {"a":1,"b":2} gave a=1;b=2; (sorted). Good, BTreeMap sorted? serde_json::Map is BTreeMap (sorted). Good.
                                let mut keys: Vec<_> = map.keys().collect();
                                keys.sort();
                                for (i, k) in keys.iter().enumerate() {
                                    let item = &map[*k];
                                    let mut new_map = match data {
                                        JsonValue::Object(m) => m.clone(),
                                        _ => serde_json::Map::new(),
                                    };
                                    new_map.insert("this".to_string(), item.clone());
                                    new_map.insert("@key".to_string(), JsonValue::String((*k).clone()));
                                    new_map.insert("@index".to_string(), JsonValue::Number(serde_json::Number::from(i as u64)));
                                    new_map.insert("@first".to_string(), JsonValue::Bool(i==0));
                                    new_map.insert("@last".to_string(), JsonValue::Bool(i==keys.len()-1));
                                    if let JsonValue::Object(im) = item {
                                        for (kk,vv) in im { new_map.insert(kk.clone(), vv.clone()); }
                                    }
                                    let new_data = JsonValue::Object(new_map);
                                    out.push_str(&render_nodes(children, &new_data, template_name)?);
                                }
                            }
                        }
                        _ => {
                            // Non-iterable: show else? Or nothing? In handlebars, each with non-array/object shows else? We'll show else if present.
                            if let Some(else_ch) = else_children {
                                out.push_str(&render_nodes(else_ch, data, template_name)?);
                            }
                        }
                    }
                } else if name == "with" {
                    let val = if let Some(p) = param {
                        eval_param_to_json(p, data, template_name)?
                    } else {
                        return Err(format!("Helper/Decorator with param at index 0 required but not found"));
                    };
                    if is_truthy(&val) {
                        // New context: if val is object, merge? Else use val as this?
                        let mut new_map = match data {
                            JsonValue::Object(m) => m.clone(),
                            _ => serde_json::Map::new(),
                        };
                        new_map.insert("this".to_string(), val.clone());
                        if let JsonValue::Object(vm) = &val {
                            for (k,v) in vm { new_map.insert(k.clone(), v.clone()); }
                        }
                        let new_data = JsonValue::Object(new_map);
                        out.push_str(&render_nodes(children, &new_data, template_name)?);
                    } else if let Some(else_ch) = else_children {
                        out.push_str(&render_nodes(else_ch, data, template_name)?);
                    }
                } else {
                    // Unknown block helper? Try as helper? In handlebars, {{#unknown}}...{{/unknown}} would look for helper "unknown". If not found, error? Or treat as section with truthiness? For simplicity, treat as if with param truthiness? But original would give "Helper not found unknown"? Let's check: what does original do for {{#unknown}}...{{/unknown}}? We didn't test. For safety, return Helper not found.
                    return Err(format!("Helper not found {}", name));
                }
            }
        }
    }
    Ok(out)
}

fn eval_param_to_json(p: &Param, data: &JsonValue, template_name: &str) -> Result<JsonValue, String> {
    match p {
        Param::Str(s) => Ok(JsonValue::String(s.clone())),
        Param::Num(n) => Ok(JsonValue::Number(n.clone())),
        Param::Bool(b) => Ok(JsonValue::Bool(*b)),
        Param::Null => Ok(JsonValue::Null),
        Param::Path(path) => Ok(lookup_path(data, path)),
        Param::Subexpr(call) => {
            let s = eval_helper(call, data, template_name)?;
            Ok(JsonValue::String(s))
        }
    }
}

fn eval_param_to_string(p: &Param, data: &JsonValue, template_name: &str) -> Result<String, String> {
    let v = eval_param_to_json(p, data, template_name)?;
    // For helpers expecting str, only String is valid, others error with type mismatch for str
    // But what about numbers/bools passed to helpers expecting str? They error, as observed.
    // So we need to check type, not convert.
    // This function is for helpers that need string; caller should check.
    // We'll just return string if String, else error will be handled by caller.
    // For now, return json_to_string? No, need to distinguish.
    // We'll let caller handle type checking by inspecting JsonValue.
    Ok(json_to_string(&v))
}

