                Ok(e)
            }
            Tok::Nil => { self.advance(); Ok(Exp::Nil) }
            Tok::True => { self.advance(); Ok(Exp::True) }
            Tok::False => { self.advance(); Ok(Exp::False) }
            Tok::Number(v, is_int, _) => { self.advance(); Ok(Exp::Number(v, is_int)) }
