            Tok::Function => Err("unexpected symbol near 'function'".to_string()),
            _ => Err(format!("unexpected symbol near '{}'", tok_to_string(self.peek()))),
        }
    }
    fn parse_table(&mut self) -> Result<Exp, String> {
        // { [fieldlist] } where fieldlist = field {sep field} [sep], sep = , or ;, field = exp | Name=exp | [exp]=exp
