                self.advance(); // =
                let v = self.parse_exp()?;
                fields.push((Some(Exp::Str(name)), v));
            } else {
                // exp (array part)
                let v = self.parse_exp()?;
                fields.push((None, v));
            }
            if self.check(&Tok::Comma) || self.check(&Tok::Semi) {
                self.advance();
