            } else {
                break;
            }
        }
        if !self.check(&Tok::RBrace) { return Err(format!("'}' expected near '{}'", tok_to_string(self.peek()))); }
        self.advance();
        Ok(Exp::Table(fields))
    }
}

fn tok_to_string(t: &Tok) -> String {
    match t {
        Tok::Ident(s) => s.clone(),
        Tok::Number(_,_,s) => s.clone(),
        Tok::Str(s) => format!("\"{}\"", s),
        Tok::Nil => "nil".to_string(),
        Tok::True => "true".to_string(),
        Tok::False => "false".to_string(),
        Tok::And => "and".to_string(),
        Tok::Or => "or".to_string(),
        Tok::Not => "not".to_string(),
        Tok::If => "if".to_string(),
        Tok::Then => "then".to_string(),
        Tok::Else => "else".to_string(),
        Tok::Elseif => "elseif".to_string(),
        Tok::End => "end".to_string(),
        Tok::Do => "do".to_string(),
        Tok::While => "while".to_string(),
        Tok::Repeat => "repeat".to_string(),
        Tok::Until => "until".to_string(),
        Tok::For => "for".to_string(),
        Tok::In => "in".to_string(),
        Tok::Local => "local".to_string(),
        Tok::Return => "return".to_string(),
        Tok::Break => "break".to_string(),
        Tok::Function => "function".to_string(),
        Tok::Goto => "goto".to_string(),
        Tok::Plus => "+".to_string(),
        Tok::Minus => "-".to_string(),
        Tok::Star => "*".to_string(),
        Tok::Slash => "/".to_string(),
        Tok::SlashSlash => "//".to_string(),
        Tok::Percent => "%".to_string(),
        Tok::Caret => "^".to_string(),
        Tok::Hash => "#".to_string(),
        Tok::Amp => "&".to_string(),
        Tok::Tilde => "~".to_string(),
        Tok::Pipe => "|".to_string(),
        Tok::GtGt => ">>".to_string(),
        Tok::LtLt => "<<".to_string(),
        Tok::DotDot => "..".to_string(),
        Tok::Lt => "<".to_string(),
        Tok::Gt => ">".to_string(),
        Tok::LtEq => "<=".to_string(),
        Tok::GtEq => ">=".to_string(),
        Tok::EqEq => "==".to_string(),
        Tok::TildeEq => "~=".to_string(),
        Tok::Eq => "=".to_string(),
        Tok::LParen => "(".to_string(),
        Tok::RParen => ")".to_string(),
        Tok::LBrace => "{".to_string(),
        Tok::RBrace => "}".to_string(),
        Tok::LBracket => "[".to_string(),
        Tok::RBracket => "]".to_string(),
        Tok::Semi => ";".to_string(),
        Tok::Colon => ":".to_string(),
        Tok::Comma => ",".to_string(),
        Tok::Dot => ".".to_string(),
        Tok::DotDotDot => "...".to_string(),
        Tok::Eof => "<eof>".to_string(),
    }
}

fn is_lvalue(e: &Exp) -> bool {
    matches!(e, Exp::Var(_) | Exp::Index(_,_) | Exp::Field(_,_))
}

