        Tok::True => "true".to_string(),
        Tok::False => "false".to_string(),
        Tok::And => "and".to_string(),
        Tok::Or => "or".to_string(),
        Tok::Not => "not".to_string(),
        Tok::If => "if".to_string(),
        Tok::Then => "then".to_string(),
        Tok::Else => "else".to_string(),
        Tok::Elseif => "elseif".to_string(),
        Tok::End => "end".to_string(),
        Tok::Do => "do".to_string(),
