fn process_line(line: &str, with_prefix: bool, message_keys: &[String], time_keys: &[String], level_keys: &[String], level_map: &HashMap<String, String>,
    main_nodes: &[Node], additional_nodes: &[Node],
    additional_values: &[String], excluded_values: &[String], always_fields: &[String], dump_all: bool,
    filter_str: &Option<String>, no_implicit: bool, print_lua: bool,
    substitution_enabled: bool, context_key: &str, placeholder_format: &str) {

    let (prefix, json_str) = if with_prefix {
        if let Some(pos) = line.find('{') {
            let pre = line[..pos].trim().to_string();
            let js = line[pos..].to_string();
            (pre, js)
        } else {
            // No '{', treat as non-JSON
            println!("\x1b[1;38;2;255;135;22m??? >\x1b[0m {}", line);
            return;
        }
    } else {
        (String::new(), line.to_string())
    };

    // Try parse JSON
    let parsed: Result<JsonValue, _> = serde_json::from_str(&json_str);
    let obj_map: serde_json::Map<String, JsonValue> = match parsed {
        Ok(JsonValue::Object(m)) => m,
        _ => {
            // Non-JSON or non-object: print ??? > with original line (full line, not json_str? For with_prefix, original line includes prefix? Earlier prefix { not json} gave ??? > with full line (prefix + json_str). Good. So use `line` (original), not json_str.
            println!("\x1b[1;38;2;255;135;22m??? >\x1b[0m {}", line);
            return;
        }
    };

    // Filter (before other processing? Filter uses original JSON, not substituted. Good. But print_lua should print even if filter fails? Yes, print_lua prints init before filtering? Earlier print_lua with filter error still printed init to stdout. Good. So generate lua_init first if print_lua and filter present.
    if let Some(filt) = filter_str {
        match eval_filter(filt, &obj_map, print_lua, no_implicit, "") {
            Ok((pass, lua_init_opt)) => {
                if let Some(init) = lua_init_opt {
                    print!("{}", init);
                }
                if !pass {
                    return; // filtered out, no output (and no error)
                }
            }
            Err(err_msg) => {
                // On filter error, print lua_init to stdout (if print_lua), error to stderr, and filter out (no main line)
                if print_lua {
                    print!("{}", print_lua_init(&obj_map));
                }
                eprintln!("{}", err_msg);
                return;
            }
        }
    } else {
        // No filter, but print_lua without filter prints nothing (as observed). Good (do nothing).
    }

    // Extract message/time/level
    let (mut message, was_string) = get_message(&obj_map, message_keys);
    let timestamp = get_timestamp(&obj_map, time_keys);
    let level = get_level(&obj_map, level_keys, level_map);

    // Substitution (only if message was string? Actually get_message returns was_string flag. If not string (number/bool), no substitution? But message is already stringified number/bool, which won't contain placeholders (except weird formats). To match original (numeric message with -s gave same, no substitution), we'll only substitute if was_string.
    let mut fblog_message = message.clone();
    if substitution_enabled && was_string {
        // Get context: literal top-level key `context_key` (not nested, not flattened)
        let ctx_opt = obj_map.get(context_key);
        fblog_message = substitute_message(&message, ctx_opt, placeholder_format);
    } else if substitution_enabled && !was_string {
        // For non-string messages, no substitution (keep as is). Good.
        fblog_message = message.clone();
    }

    // Build data for template: original JSON values + fblog_ vars
    // Data is JsonValue::Object with all original keys (as is, with original types) plus fblog_timestamp, fblog_message, fblog_level, fblog_prefix
    let mut data_map = serde_json::Map::new();
    for (k, v) in &obj_map {
        data_map.insert(k.clone(), v.clone());
    }
    data_map.insert("fblog_timestamp".to_string(), JsonValue::String(timestamp.clone()));
    data_map.insert("fblog_message".to_string(), JsonValue::String(fblog_message.clone()));
    data_map.insert("fblog_level".to_string(), JsonValue::String(level.clone()));
    data_map.insert("fblog_prefix".to_string(), JsonValue::String(prefix.clone()));
    let data = JsonValue::Object(data_map);

    // Render main line
    match render_nodes(main_nodes, &data, "main_line") {
        Ok(s) => {
            println!("{}", s);
        }
        Err(e) => {
            // Failed to process line: print to stdout with red ??? >
            println!("\x1b[1;31m??? >\x1b[0m Failed to process line: Error rendering \"main_line\" line 1, col 1: {}", e);
            return; // No additional values if main fails? Original: when main fails, does it still show additional? Likely not (since main failed, return). Let's assume return.
        }
    }

    // Additional values
    // Determine which keys to show:
    // - If dump_all (either -d or -x): show all flattened sorted, excluding excluded_values (exact match)
    // - Else (no dump): show always_fields (in order) + additional_values (in order), each expanded via prefix matching, in that order (always first, then additional). Duplicates preserved (show twice if duplicate requested).
    if dump_all {
        let flat = flatten_json(&obj_map);
        // flat is BTreeMap sorted. Iterate sorted.
        for (k, v) in flat {
            if excluded_values.contains(&k) {
                continue;
            }
            // Build data for additional: key, value, plus original? Additional template can use {{key}}, {{value}}, plus maybe other vars? Original additional template uses {{key}} and {{value}} only? But could it use other vars like {{fblog_message}}? Possibly (since data includes all?). Let's include all data plus key/value.
            let mut add_map = match &data {
                JsonValue::Object(m) => m.clone(),
                _ => serde_json::Map::new(),
            };
            add_map.insert("key".to_string(), JsonValue::String(k.clone()));
            add_map.insert("value".to_string(), JsonValue::String(v.clone()));
            let add_data = JsonValue::Object(add_map);
            match render_nodes(additional_nodes, &add_data, "additional_value") {
                Ok(s) => println!("{}", s),
                Err(e) => {
                    println!("\x1b[1;31m   ??? >\x1b[0m Failed to process additional value: Error rendering \"additional_value\" line 1, col 1: {}", e);
                }
            }
        }
    } else {
        // No dump: always + additional
        let flat = if always_fields.is_empty() && additional_values.is_empty() {
            // No additional to show, skip flattening (optimization)
            BTreeMap::new()
        } else {
            flatten_json(&obj_map)
        };
        // Helper to find matches for a requested key
        let find_matches = |req: &str| -> Vec<(String, String)> {
            let mut res = Vec::new();
            for (k, v) in &flat {
                if k == req || k.starts_with(&format!("{} > ", req)) || k.starts_with(&format!("{}[", req)) {
                    res.push((k.clone(), v.clone()));
                }
            }
            // flat is sorted, so res is sorted. Good.
            res
        };
        // Always first
        for req in always_fields {
            for (k, v) in find_matches(req) {
                let mut add_map = match &data {
                    JsonValue::Object(m) => m.clone(),
                    _ => serde_json::Map::new(),
                };
                add_map.insert("key".to_string(), JsonValue::String(k.clone()));
                add_map.insert("value".to_string(), JsonValue::String(v.clone()));
                let add_data = JsonValue::Object(add_map);
                match render_nodes(additional_nodes, &add_data, "additional_value") {
                    Ok(s) => println!("{}", s),
                    Err(e) => {
                        println!("\x1b[1;31m   ??? >\x1b[0m Failed to process additional value: Error rendering \"additional_value\" line 1, col 1: {}", e);
                    }
                }
            }
        }
        // Then additional_values
        for req in additional_values {
            for (k, v) in find_matches(req) {
                let mut add_map = match &data {
                    JsonValue::Object(m) => m.clone(),
                    _ => serde_json::Map::new(),
                };
                add_map.insert("key".to_string(), JsonValue::String(k.clone()));
                add_map.insert("value".to_string(), JsonValue::String(v.clone()));
                let add_data = JsonValue::Object(add_map);
                match render_nodes(additional_nodes, &add_data, "additional_value") {
                    Ok(s) => println!("{}", s),
                    Err(e) => {
                        println!("\x1b[1;31m   ??? >\x1b[0m Failed to process additional value: Error rendering \"additional_value\" line 1, col 1: {}", e);
                    }
                }
            }
        }
    }
}

