fn parse_until(template: &str, pos: &mut usize, end_name: Option<&str>) -> Result<(Vec<Node>, Option<String>), (String, usize)> {
    let mut nodes = Vec::new();
    let len = template.len();
    while *pos < len {
        if let Some(rel) = template[*pos..].find("{{") {
            let abs_start = *pos + rel;
            if abs_start > *pos {
                nodes.push(Node::Text(template[*pos..abs_start].to_string()));
                *pos = abs_start;
                continue;
            }
            // At {{
            let is_triple = template[*pos..].starts_with("{{{");
            let open_len = if is_triple { 3 } else { 2 };
            let close_pat = if is_triple { "}}}" } else { "}}" };
            if let Some(end_rel) = template[*pos+open_len..].find(close_pat) {
                let abs_end = *pos + open_len + end_rel;
                let inner_raw = &template[*pos+open_len..abs_end];
                let mut inner = inner_raw.trim();
                if inner.starts_with('~') { inner = inner[1..].trim_start(); }
                if inner.ends_with('~') { inner = inner[..inner.len()-1].trim_end(); }
                if inner.is_empty() {
                    return Err(("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline".to_string(), *pos+3));
                }
                if inner.starts_with('!') {
                    *pos = abs_end + close_pat.len();
                    continue;
                }
                if inner.starts_with('#') {
                    let rest = inner[1..].trim_start();
                    if rest.is_empty() {
                        return Err(("expected identifier".to_string(), *pos+3));
                    }
                    let (name, param_str) = split_first_word(rest);
                    let param = if param_str.trim().is_empty() { None } else { Some(parse_param(param_str.trim(), template, abs_start)?) };
                    *pos = abs_end + close_pat.len();
                    let (children, else_children) = parse_section_block(template, pos, &name)?;
                    nodes.push(Node::Section { name, param, children, else_children });
                    continue;
                }
                if inner.starts_with('/') {
                    let rest = inner[1..].trim();
                    if let Some(expected) = end_name {
                        if rest == expected {
                            *pos = abs_end + close_pat.len();
                            return Ok((nodes, Some(format!("/{}", rest))));
                        } else {
                            return Err((format!("mismatched closing tag"), abs_start+3));
                        }
                    } else {
                        return Err((format!("closing tag without opening"), abs_start+3));
                    }
                }
                if inner == "else" || inner.starts_with("else ") || inner.starts_with("else\t") {
                    if end_name.is_some() {
                        *pos = abs_end + close_pat.len();
                        return Ok((nodes, Some("else".to_string())));
                    } else {
                        return Err(("expected identifier".to_string(), abs_start+3));
                    }
                }
                if inner.starts_with('&') {
                    let rest = inner[1..].trim();
                    if rest.is_empty() {
                        return Err(("expected identifier".to_string(), abs_start+3));
                    }
                    let node = parse_mustache(rest, template, abs_start)?;
                    nodes.push(node);
                    *pos = abs_end + close_pat.len();
                    continue;
                }
                if inner.starts_with('>') {
                    *pos = abs_end + close_pat.len();
                    continue;
                }
                let node = parse_mustache(inner, template, abs_start)?;
                nodes.push(node);
                *pos = abs_end + close_pat.len();
                continue;
            } else {
                let col = template.len() + 1;
                return Err(("expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace".to_string(), col));
            }
        } else {
            nodes.push(Node::Text(template[*pos..].to_string()));
            *pos = len;
            break;
        }
    }
    if let Some(expected) = end_name {
        let col = template.len() + 1;
        return Err((format!("missing closing tag for {}", expected), col));
    }
    Ok((nodes, None))
}

fn parse_section_block(template: &str, pos: &mut usize, name: &str) -> Result<(Vec<Node>, Option<Vec<Node>>), (String, usize)> {
    let (children, term) = parse_until(template, pos, Some(name))?;
    match term {
        Some(t) if t == "else" => {
            let (else_children, term2) = parse_until(template, pos, Some(name))?;
            match term2 {
                Some(t2) if t2 == format!("/{}", name) => Ok((children, Some(else_children))),
                _ => {
                    let col = template.len() + 1;
                    Err((format!("missing closing tag for {}", name), col))
                }
            }
        }
        Some(t) if t == format!("/{}", name) => Ok((children, None)),
        None => {
            let col = template.len() + 1;
            Err((format!("missing closing tag for {}", name), col))
        }
        _ => {
            let col = template.len() + 1;
            Err((format!("missing closing tag for {}", name), col))
        }
    }
}

